-- SQLite 3 (works the same conceptually in PostgreSQL)
PRAGMA journal_mode = WAL;

CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  owner TEXT NOT NULL,
  balance_cents INTEGER NOT NULL CHECK (balance_cents >= 0)
);

INSERT INTO accounts VALUES (1, 'alice', 10000), (2, 'bob', 2500);

-- A correct transfer: one unit of work, guarded by a constraint
BEGIN;

UPDATE accounts
   SET balance_cents = balance_cents - 5000
 WHERE id = 1 AND balance_cents >= 5000;
-- application checks here: if 0 rows changed, the funds were not there

UPDATE accounts
   SET balance_cents = balance_cents + 5000
 WHERE id = 2;

COMMIT;

-- If anything failed before COMMIT: ROLLBACK;

-- Partial undo with savepoints
BEGIN;
SAVEPOINT before_bonus;
UPDATE accounts SET balance_cents = balance_cents + 100 WHERE id = 2;
ROLLBACK TO before_bonus;  -- bonus step undone, transaction still alive
COMMIT;

-- PostgreSQL notes:
--   BEGIN ISOLATION LEVEL SERIALIZABLE;  for strict invariants
--   SERIALIZATION FAILURE -> retry the whole transaction
